# 동적 쿼리 - 조건이 없으면
itemRepository.findAll(new ItemSearchCond(null, null));

#   select id, item_name, price, quantity from item

# 상품명만
itemRepository.findAll(new ItemSearchCond("itemA", null));

#   select id, item_name, price, quantity from item
#   where item_name like concat('%',?,'%')
#   {1: 'itemA'}

# 가격만
itemRepository.findAll(new ItemSearchCond(null, 10000));

#   select id, item_name, price, quantity from item
#   where price <= ?
#   {1: 10000}

# 둘 다
itemRepository.findAll(new ItemSearchCond("itemA", 10000));

#   select id, item_name, price, quantity from item
#   where item_name like concat('%',?,'%') and price <= ?
#   {1: 'itemA', 2: 10000}

# 네 가지 SQL 이 나온다. 조건이 넷이면 열여섯 가지

# 띄어쓰기를 빠뜨리면
#   select ... from itemwhere item_name like ?
# org.springframework.jdbc.BadSqlGrammarException: [42001-232]

# 실행해 봐야 안다
